INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (64, 'Jahitan collar atau cuff tidak terbentuk dengan benar', 'Hasil runstitch pada collar atau cuff tidak rapi, tidak sesuai jalur, atau jahitan tidak terbentuk secara konsisten.', 'Posisi material tidak tepat, parameter jahitan tidak sesuai, material tidak terdeteksi, atau mekanisme jahit mengalami gangguan.', 'Periksa posisi collar atau cuff, parameter program, sensor pendeteksi, dan area mekanisme jahit. Lakukan pengujian menggunakan material yang sesuai.', 'Hentikan siklus otomatis sebelum melakukan pemeriksaan di area jarum dan mekanisme jahit. Jangan menyentuh bagian bergerak saat mesin aktif.', 'Data spesifikasi MAICA UAM-03 dan panduan pemeriksaan umum mesin runstitch otomatis');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (64, 'Benang jahitan sering putus', 'Benang putus berulang saat proses menjahit collar atau cuff.', 'Jarum atau benang tidak sesuai, jalur benang terganggu, tegangan benang tidak tepat, atau mekanisme jahit mengalami hambatan.', 'Periksa kondisi dan pemasangan jarum, jalur benang, tegangan benang, serta area mekanisme jahit. Ganti komponen yang rusak sesuai prosedur mesin.', 'Matikan mesin sebelum mengganti jarum atau melakukan pemeriksaan pada area jahit.', 'Data spesifikasi MAICA UAM-03 dan panduan pemeriksaan umum sistem jahit');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (64, 'Tekanan udara pneumatik tidak mencukupi', 'Aktuator bergerak lambat, lemah, atau salah satu tahapan otomatis tidak berjalan.', 'Tekanan udara di bawah kebutuhan 7 bar, suplai udara terganggu, atau terdapat kebocoran pada selang dan sambungan.', 'Periksa tekanan suplai dan pastikan sesuai kebutuhan mesin. Periksa selang serta sambungan yang dapat diakses untuk mengetahui adanya kebocoran.', 'Lepaskan tekanan udara sebelum membongkar komponen pneumatik. Jangan memasukkan tangan ke area aktuator saat sistem dapat bergerak.', 'Data spesifikasi MAICA UAM-03 dan panduan pemeriksaan umum sistem pneumatik');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (64, 'Trimming otomatis tidak bekerja dengan benar', 'Benang atau bagian material tidak terpotong setelah proses jahit, atau hasil trimming tidak konsisten.', 'Mekanisme trimming terhambat, pisau atau komponen pemotong tidak bekerja optimal, sensor atau parameter trimming bermasalah.', 'Periksa area trimming dari sisa material, periksa kondisi komponen pemotong dan sensor yang dapat diakses, lalu periksa parameter trimming melalui sistem kontrol.', 'Matikan mesin dan pastikan mekanisme berhenti sebelum memeriksa pisau atau area trimming. Jangan menyentuh pisau pemotong secara langsung.', 'Data spesifikasi MAICA UAM-03 dan panduan pemeriksaan umum sistem trimming');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (64, 'Ukuran collar atau cuff tidak sesuai program', 'Mesin menghasilkan ukuran collar atau cuff yang berbeda dari ukuran yang dipilih.', 'Parameter ukuran tidak sesuai, automatic size change tidak berpindah ke ukuran yang benar, material tidak terdeteksi, atau program tidak sesuai.', 'Periksa ukuran yang dipilih pada sistem kontrol, parameter automatic size change, sensor, dan posisi material. Lakukan pengujian ulang setelah parameter dikonfirmasi.', 'Hentikan siklus sebelum melakukan penyetelan. Jangan mengubah parameter produksi tanpa mengikuti prosedur pengoperasian mesin.', 'Data spesifikasi MAICA UAM-03 dan panduan pemeriksaan umum automatic size change');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (64, 'Proses stacking otomatis tidak berjalan', 'Collar atau cuff yang sudah diproses tidak tersusun atau tidak berpindah ke posisi stacking dengan benar.', 'Jalur perpindahan material terhalang, sensor tidak mendeteksi produk, aktuator pneumatik bermasalah, atau mekanisme stacker terganggu.', 'Periksa jalur material, sensor yang dapat diakses, tekanan udara, dan area stacker dari hambatan. Uji kembali setelah hambatan diatasi.', 'Hentikan mesin sebelum mengambil material dari area stacker. Jangan menjangkau mekanisme yang dapat bergerak otomatis.', 'Data spesifikasi MAICA UAM-03 dan panduan pemeriksaan umum sistem stacking');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (64, 'Sistem kontrol komputer atau elektronik mengalami gangguan', 'Program tidak berjalan sesuai perintah, alarm muncul, atau mesin tidak melanjutkan siklus otomatis.', 'Parameter atau program bermasalah, sensor memberikan sinyal tidak sesuai, komunikasi sistem kontrol terganggu, atau terjadi gangguan suplai listrik.', 'Catat pesan alarm pada sistem kontrol, periksa kondisi sensor dan suplai listrik, kemudian lakukan pemeriksaan program sesuai prosedur mesin.', 'Mesin menggunakan suplai 380 V / 50 Hz. Pemeriksaan panel listrik hanya boleh dilakukan oleh personel yang kompeten dan setelah sumber energi diisolasi.', 'Data spesifikasi MAICA UAM-03 dan panduan pemeriksaan umum sistem kontrol');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (64, 'Mesin berhenti di tengah siklus otomatis', 'Proses menjahit, trimming, perubahan ukuran, atau stacking berhenti sebelum seluruh siklus selesai.', 'Sensor tidak mendeteksi kondisi yang diharapkan, tekanan udara tidak mencukupi, material macet, atau sistem kontrol mendeteksi kondisi abnormal.', 'Periksa indikator atau alarm pada sistem kontrol, kemudian periksa sensor, tekanan udara, posisi material, dan area mekanisme sesuai urutan pemeriksaan.', 'Jangan menonaktifkan atau melewati interlock keselamatan untuk memaksa mesin melanjutkan siklus. Pastikan mesin berhenti sebelum pemeriksaan.', 'Data spesifikasi MAICA UAM-03 dan panduan pemeriksaan umum mesin otomatis');
